/// Returns the spec-declared role for `profile_id`, if any.
pub fn profile_role(profile_id: &str) -> Option<ProfileRole> {
    PROFILE_ROLES
        .binary_search_by(|(id, _)| (*id).cmp(profile_id))
        .ok()
        .map(|index| PROFILE_ROLES[index].1)
}

/// Returns every profile id whose spec role is `role`, in sorted order.
pub fn profile_ids_with_role(role: ProfileRole) -> Vec<&'static str> {
    PROFILE_ROLES
        .iter()
        .filter(|(_, r)| *r == role)
        .map(|(id, _)| *id)
        .collect()
}
